// The mystery card of the Upcoming events page. Every detail is hidden ("will be revealed soon").
// You do not edit this file. Everything (on/off, hackathon / workshop / online, the event name, the dates,
// the details) is in site/upcomingConfig.js. The look (1 to 5) comes by itself, matching the popup, and moves on with every new event.
//   look 1 = Signal (this file) , looks 2-5 = Terminal / Dossier / Blueprint / Vault (site/TeaserCards.jsx),
//   looks 6 and up = the newer cards (site/TeaserCardsNew.jsx)
import { Suspense, lazy } from 'react';
import { Reveal } from './ui';
import PosterStage from './PosterStage';
import { CardTitle } from './NameReveal';
import { Actions, FieldValue, Guard, getDesign, isTeaserLive, useTeaser } from './teaserCore';
import './HackathonTeaser.css';

export { isTeaserLive };

const Cards = lazy(() => import('./TeaserCards'));
const NewCards = lazy(() => import('./TeaserCardsNew'));   // looks 6 and up

/* look 1: radar + glowing question mark */
function Signal({ t }) {
  const { copy } = t;
  return (
    <article className={`s-mys t-${t.type} is-${t.phase}`} aria-label={t.label}>
      <PosterStage kind="card">
      <div className="s-mys-vis" aria-hidden="true">
        <div className="s-mys-radar">
          <i /><i /><i />
          <b className="s-mys-sweep" />
          <em className="s-mys-blip b1" /><em className="s-mys-blip b2" /><em className="s-mys-blip b3" />
        </div>
        <div className="s-mys-q">?</div>
        <div className="s-mys-hex"><span>{t.hex}  {t.hex}  </span></div>
        <span className="s-mys-tag">{copy.tag}</span>
      </div>
      </PosterStage>

      <div className="s-mys-body">
        <div className="s-row">
          <span className="s-mys-flag"><i /> {copy.flag}</span>
          <span className="s-mys-file">{copy.file}</span>
        </div>

        <CardTitle t={t} className="s-mys-title" />
        <p className="s-mys-lede">{copy.lede}</p>
        <p className="s-mys-desc">{copy.desc}</p>

        {t.live ? (
          <div className="s-live"><i /> It&apos;s live</div>
        ) : (
          <>
            <div className="s-mys-cdl">{t.counting ? 'Starts in' : copy.wait}</div>
            <div
              className={`s-cd ${t.waiting ? 'is-idle' : ''}`}
              role={t.counting ? 'timer' : 'group'}
              aria-label={t.counting ? `Starts in ${t.c.d} days ${t.c.h} hours ${t.c.m} minutes` : 'Timer not started yet'}
            >
              {t.cells.map(([name, v]) => (
                <div className="s-cd-cell" key={name}>
                  <b key={v}>{typeof v === 'number' ? String(v).padStart(2, '0') : v}</b>
                  <span>{name}</span>
                </div>
              ))}
            </div>
          </>
        )}

        <div className="s-mys-grid">
          {t.fields.map((f) => (
            <div key={f.k} className={`s-mys-cell ${f.state === 'open' ? 'is-open' : 'is-lock'} ${f.state === 'denied' ? 'is-denied' : ''} ${f.state === 'ready' ? 'is-ready' : ''}`}>
              <span className="s-mys-k">{f.k}</span>
              <b className={`s-mys-v ${f.state === 'open' ? 's-mys-real' : f.state === 'idle' ? 's-mys-soon' : f.state === 'ready' ? 's-mys-ready' : 's-mys-code'}`}>
                <FieldValue f={f} />
              </b>
            </div>
          ))}
        </div>

        <div className="s-mys-prog" role="progressbar" aria-label="Compiling" aria-valuemin={0} aria-valuemax={100} aria-valuenow={t.shown}>
          <span>{t.status}</span>
          <div className="s-mys-track"><i style={{ width: `${t.shown}%` }} /></div>
          <span>{t.shown}%</span>
        </div>

        <Actions t={t} />
      </div>
    </article>
  );
}

export default function HackathonTeaser() {
  const t = useTeaser();
  if (!t.visible) return null;
  const STYLE = getDesign().card;
  return (
    <Reveal>
      {STYLE === 1 ? (
        <Signal t={t} />
      ) : (
        <Guard>
          <Suspense fallback={<div className="tc-wait" aria-hidden="true" />}>
            {STYLE <= 5 ? <Cards t={t} style={STYLE} /> : <NewCards t={t} style={STYLE} />}
          </Suspense>
        </Guard>
      )}
    </Reveal>
  );
}
